-- =====================================================================
--  CRM Groupe — lot 7 : le référentiel DTU rejoint BTP Expertise
--  À exécuter dans Supabase > SQL Editor, après lot5-btp.sql.
--  Idempotent : relançable sans rien perdre.
--
--  Les 20 fiches viennent du tableau de bord RGD Renova, où elles avaient été
--  rédigées. Chacune porte son résumé, ses points clés et ses erreurs fréquentes
--  (titre + détail), et le lien vers la norme sur la boutique AFNOR.
--
--  Les numéros sont normalisés en « NF DTU x.y » pour rejoindre les fiches déjà
--  créées par le lot 5 : une fiche existante est enrichie, pas dupliquée. Les points
--  de contrôle saisis à la main dans le CRM (colonne checkpoints) ne sont pas touchés.
-- =====================================================================

-- ---------- Le contenu d'une fiche, tel qu'il a été rédigé ----------
alter table public.dtu_sheets add column if not exists summary text;
alter table public.dtu_sheets add column if not exists key_points jsonb not null default '[]'::jsonb;
alter table public.dtu_sheets add column if not exists common_errors jsonb not null default '[]'::jsonb;
alter table public.dtu_sheets add column if not exists essential boolean not null default false;

comment on column public.dtu_sheets.summary is 'Ce que couvre la norme, en clair.';
comment on column public.dtu_sheets.key_points is 'Points clés : [{titre, detail}] — la règle telle qu''elle s''applique sur le chantier.';
comment on column public.dtu_sheets.common_errors is 'Erreurs fréquentes : [{titre, detail}] — ce qui est constaté en expertise.';
comment on column public.dtu_sheets.essential is 'Fiche mise en avant dans la liste.';

-- ---------- Les fiches ----------
insert into public.dtu_sheets (code, title, domain, summary, key_points, common_errors, link, essential, position) values
  ('NF DTU 20.1', 'Maçonnerie de petits éléments', 'Maçonnerie', 'Le DTU fondamental pour tout maçon. Cadre la maçonnerie de petits éléments (parpaings, briques, blocs béton cellulaire) pour murs porteurs, refends et chaînages.', '[{"titre":"Choix des matériaux selon classe d''exposition","detail":"Intérieur sec : parpaing creux standard B40. Milieu humide (cuisine, SDB, vide sanitaire) et façade exposée à la pluie : parpaing plein, brique pleine ou parpaing hydrofuge. Murs enterrés ou pignons très exposés : béton banché ou parpaing plein hydrofugé sur toute hauteur. Toujours vérifier la classe d''exposition NF EN 998-2 sur la palette avant achat."},{"titre":"Mortier de pose : dosage minimum","detail":"Pour joints minces (3-5 mm) : mortier-colle industriel pré-dosé. Pour joints traditionnels (10-15 mm) : 1 volume ciment + 3 volumes sable + eau, ou 1 volume chaux NHL + 3 volumes sable sur bâti ancien. Dosage minimum réglementaire : 350 kg de liant par m³ de mortier fini. Jamais de mortier bâtard chaux-ciment sur mur porteur (perte de résistance)."},{"titre":"Chaînages horizontaux obligatoires","detail":"Ceinturage en tête de chaque plancher, sablières en pignon, linteaux continus. Section mini 15×15 cm en béton armé avec 4 HA10 + cadres tous les 20 cm. Le chaînage doit faire le tour complet du bâtiment, sans interruption. Sans chaînage horizontal, les murs travaillent isolément et fissurent dès le moindre tassement."},{"titre":"Linteaux : portée et appuis","detail":"Portée maxi 1,80 m sans chaînage de couronnement, appui de 20 cm mini de chaque côté. Au-delà de 1,80 m : poutre béton armé calculée ou linteau préfabriqué avec déclaration de résistance. Sur baies en angle, prévoir une suspente ou un cadre de renfort. Un linteau qui fléchit fissure systématiquement toute la maçonnerie au-dessus."},{"titre":"Joints verticaux décalés","detail":"Décalage minimum 1/3 de la longueur du bloc (10 cm pour parpaing 50×20). Jamais de joints alignés sur 2 rangées consécutives. Ce décalage répartit les charges et empêche les fissurations en colonne. La règle est encore plus importante en zone sismique (zones 3, 4, 5)."},{"titre":"Chaînages verticaux aux angles","detail":"Obligatoires aux 4 angles du bâtiment, aux croisements de refends et tous les 5 m maxi le long des grands linéaires. Section 15×15 cm béton armé avec 4 HA12 + cadres. Le chaînage vertical ancre le chaînage horizontal et empêche le mur de basculer sous l''effet du vent ou des poussées."},{"titre":"Enduit de protection extérieur","detail":"Obligatoire sur parpaing creux non hydrofuge en façade exposée. Enduit traditionnel 3 couches (15-25 mm) ou monocouche industriel agréé. Sans enduit, l''eau pénètre les alvéoles et provoque éclatement par gel. La face Ouest et les pignons sont les plus exposés."}]'::jsonb, '[{"titre":"Linteaux trop courts ou sans appui suffisant","detail":"Appui < 20 cm de chaque côté = ruine assurée. La maçonnerie fissure d''abord aux angles supérieurs de la baie, puis le linteau bascule. Toujours vérifier l''appui réel après scellement, surtout sur baies récupérées."},{"titre":"Oubli des chaînages verticaux dans les angles","detail":"Sans chaînage vertical, les angles travaillent en flexion et se désolidarisent. Résultat : fissures verticales nettes à 5-15 cm de l''angle, traversantes. Réparation lourde car il faut décrouter et reprendre la liaison."},{"titre":"Joints verticaux continus","detail":"Quand les joints verticaux s''alignent sur 3-4 rangées, la maçonnerie travaille comme deux murs collés au lieu d''un seul. Fissuration en colonne dès la première année."},{"titre":"Pose sur support non plan","detail":"Variation de niveau > 5 mm entre 2 blocs consécutifs = désaffleurs visibles + sollicitations parasites. Toujours dresser la première rangée au cordeau, contrôler à la règle de 2 m."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-20-1', true, 10),
  ('NF DTU 13.3', 'Dallages — conception, calcul, exécution', 'Maçonnerie', 'Tous les dallages béton sur terre-plein. Très utile en rénovation lourde (création de plancher bas, agrandissement, garage).', '[{"titre":"Hérisson de fond de forme","detail":"Pierres concassées calibrées 20/40 ou 40/80 sur 20 cm d''épaisseur mini. Mise en œuvre par couches de 10 cm compactées à la dame ou plaque vibrante. Le hérisson coupe les remontées capillaires et stabilise le sol. Sans hérisson correct, le dallage repose sur sol meuble → fissuration garantie."},{"titre":"Film polyane d''étanchéité","detail":"Polyane 200 microns mini, posé sur le hérisson, recouvrement 20 cm aux joints, remonté de 10 cm en périphérie sur les murs. Tout trou = remontée d''humidité. Vérifier l''absence de déchirures juste avant coulage. C''est la dernière barrière contre l''humidité du sol."},{"titre":"Isolation sous-dallage (si chauffé)","detail":"Polystyrène extrudé (XPS) ou expansé haute densité (EPS HD). Épaisseur 8 à 12 cm selon RT2012/RE2020. Résistance à la compression > 200 kPa pour usage logement. L''isolant doit supporter le coulage sans s''écraser."},{"titre":"Treillis soudé et son positionnement","detail":"Treillis ST25C minimum (5 mm tous les 15 cm) posé sur cales béton à 1/3 de la dalle depuis le bas, jamais directement sur le polyane. Recouvrement de 2 mailles minimum aux jonctions. Le treillis ne renforce que s''il est dans la zone tendue (bas pour charges en flexion)."},{"titre":"Épaisseur de la dalle","detail":"12 cm en logement courant, 15 cm si véhicule (garage), 18-20 cm si engins. Au-dessous de 12 cm = risque de fissuration au moindre poinçonnement. Toujours respecter la pente de finition par-dessus, pas dans l''épaisseur structurelle."},{"titre":"Joints de retrait","detail":"Sciés à 1/3 de l''épaisseur (4 cm pour dalle 12 cm), espacés de 5 m maxi, dans les 48h après coulage. Maillage carré, jamais rectangulaire. Sans joints, le béton fissure aléatoirement au séchage : on choisit où la fissure aura lieu."},{"titre":"Joints de désolidarisation périphériques","detail":"Bande compressible (mousse, polystyrène) de 10 mm contre tous les murs, poteaux et émergences. La dalle doit pouvoir bouger thermiquement sans pousser sur la maçonnerie. Sans ce joint : fissure en pied de mur ou décollement plinthe."}]'::jsonb, '[{"titre":"Polyane troué ou mal recouvert","detail":"Une déchirure non vue = remontée capillaire localisée → tache d''humidité permanente sur le sol fini, décollement carrelage. Toujours faire un dernier tour visuel avant coulage."},{"titre":"Treillis posé directement sur le sol","detail":"Treillis au fond = pas dans la zone tendue, donc inefficace. La dalle fissurera comme s''il n''y avait pas de treillis. Toujours utiliser des cales béton ou plastique (5 cm) pour le surélever."},{"titre":"Pas de joint de désolidarisation","detail":"Sans joint, le retrait du béton arrache la maçonnerie en pied de mur. Fissure horizontale typique à la jonction sol-mur, désordres irréversibles."},{"titre":"Charges roulantes non anticipées","detail":"Garage prévu pour piéton puis utilisé pour véhicule = poinçonnement central, fissuration en étoile. Toujours demander au client l''usage prévu (et futur) avant chiffrage."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-13-3', false, 20),
  ('NF DTU 26.1', 'Enduits aux mortiers', 'Maçonnerie', 'Enduits traditionnels (chaux, ciment) et industriels. Indispensable sur bâti ancien — un mauvais enduit emprisonne l''humidité et détruit le mur.', '[{"titre":"Reconnaissance du support","detail":"Avant tout enduit : identifier le support (pierre, brique, parpaing, bâti ancien hétérogène) et son état (sain, friable, humide). Sonner le support au marteau pour repérer les zones creuses. Un mauvais diagnostic = enduit qui cloque et tombe."},{"titre":"Sur bâti ancien : chaux exclusivement","detail":"Pierre, terre, brique pleine ancienne : chaux NHL 2 à 3,5 selon dureté du support. Le ciment bloque la vapeur d''eau, l''humidité reste piégée dans le mur, le salpêtre apparaît et le mortier décolle. Sur bâti ancien, la chaux laisse respirer le mur."},{"titre":"3 couches traditionnelles","detail":"Gobetis (accroche, 5 mm, mortier liquide projeté), corps d''enduit (durcissement et planéité, 10-15 mm), finition (esthétique et étanchéité, 5-8 mm). Chaque couche doit être moins dosée que la précédente (loi de dégressivité). Toujours laisser sécher entre couches."},{"titre":"Épaisseur totale","detail":"15 mm minimum sur support plan, 20 à 25 mm sur support irrégulier. Au-delà de 25 mm en une fois : risque de retrait excessif et fissuration. Sur trous profonds : combler en plusieurs passes avec délai de séchage."},{"titre":"Délais de séchage entre couches","detail":"Gobetis → corps d''enduit : 24 à 48 h selon T°. Corps d''enduit → finition : 5 à 7 jours minimum. Application trop rapide = couche précédente arrachée par le retrait de la suivante."},{"titre":"Conditions météo d''application","detail":"Pas d''application si T° < 5°C ou > 30°C, ni par grand vent, ni en plein soleil de mi-journée. Le séchage rapide fissure, le gel détruit la prise. Bâcher si nécessaire, ou attendre les bonnes conditions."},{"titre":"Humidification du support","detail":"Humidifier la veille au pulvérisateur sans détremper, surtout sur brique ou parpaing. Un support sec pompe l''eau du mortier qui ne fait plus prise correctement → faïençage et perte d''adhérence."}]'::jsonb, '[{"titre":"Ciment sur bâti ancien","detail":"Erreur classique mais grave : le ciment emprisonne l''humidité du mur ancien (qui remonte par capillarité), provoque salpêtre, cloques et décollement en quelques années. La seule réparation : tout déposer et refaire à la chaux."},{"titre":"Pas de gobetis","detail":"Sans gobetis (couche d''accrochage liquide), le corps d''enduit ne pénètre pas les pores du support. Décollement par plaques après quelques années, surtout en façade exposée Sud-Ouest."},{"titre":"Application sur support sec et chaud","detail":"Le mortier perd son eau par évaporation et succion du support avant la prise. Résultat : faïençage généralisé (microfissures en réseau) et adhérence quasi nulle."},{"titre":"Couche trop épaisse en une passe","detail":"Au-delà de 25 mm en une fois, le retrait crée des fissures profondes. Toujours travailler par couches, en respectant les délais de séchage."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-26-1', true, 30),
  ('NF DTU 25.41', 'Plaques de plâtre sur ossature métallique', 'Plâtrerie', 'Probablement le DTU le plus utilisé en rénovation. Cloisons, doublages et plafonds en plaques de plâtre vissées sur rails/montants.', '[{"titre":"Entraxe des montants","detail":"Entraxe standard : 60 cm pour BA13 simple peau hauteur < 2,60 m. Au-delà ou pour BA13 hauteur 3 m : entraxe 40 cm ou passer en double peau. Mauvais entraxe = ondulations visibles en lumière rasante, surtout sur paroi peinte mat."},{"titre":"Choix du profilé selon hauteur","detail":"Cloison hauteur < 2,60 m : montants 48 mm (M48). Hauteur 2,60 à 3,20 m : M70 ou M48 doublés. Hauteur > 3,20 m : M90 ou M100. Toujours majorer en cas de hauteur libre exceptionnelle (cathédrale)."},{"titre":"Vissage des plaques","detail":"Vis TTPC (Tête Trompette Phillips Cruciforme) 25 mm pour BA13 simple peau, 35 mm pour double peau. Espacement vis : 30 cm sur rives, 50 cm en partie courante. Visser sans casser le carton (légèrement noyé, pas enfoncé)."},{"titre":"Traitement des joints en 3 passes","detail":"Passe 1 : collage bande papier dans l''enduit frais. Passe 2 (24h après) : enduit de lissage débordant de 15 cm de part et d''autre. Passe 3 : finition fine, ponçage léger. Sans 3 passes : fissures inévitables après 6 mois."},{"titre":"Bandes à joints en papier","detail":"Bandes papier > bandes auto-adhésives en fibre de verre. Le papier est plus solide à long terme et se noie mieux dans l''enduit. Bandes auto-adhésives uniquement pour réparation rapide ou doublage léger."},{"titre":"Isolant phonique dans la cloison","detail":"Laine de roche ou de verre 45 mm mini pour atténuation 35-40 dB. Pour cloisons SDB / chambre : 70 mm + plaque acoustique type Phonik. Sans isolant, la cloison résonne et transmet les bruits aériens et d''impact."},{"titre":"Pied de cloison","detail":"Bande résiliente (caoutchouc ou mousse) sous le rail bas pour désolidariser de la chape. Écart 10 mm au sol pour permettre le calfeutrement. Sans désolidarisation : remontées d''eau capillaires et transmission des vibrations."}]'::jsonb, '[{"titre":"Entraxe 60 cm en BA13 hauteur 3 m","detail":"La plaque fléchit entre les montants → ondulations visibles à la lumière rasante, surtout sur peinture mat ou satinée. Quasi impossible à rattraper sans démontage partiel."},{"titre":"Vis fraisées trop fort","detail":"Vis enfoncée qui casse le carton extérieur → la plaque n''est plus maintenue, micro-fissures à terme. Toujours utiliser un embout limiteur de couple."},{"titre":"Bandes mal noyées","detail":"Bande visible en relief sous la peinture, fissure qui apparaît au bout de quelques mois. Bien forcer la bande dans l''enduit frais, sans bulles."},{"titre":"Pas d''isolant phonique","detail":"Cloison \"tambour\" qui résonne aux moindres impacts. Sur cloisons mitoyennes (chambre/séjour), l''isolation est indispensable au confort."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-25-41', true, 40),
  ('NF DTU 25.42', 'Doublages collés (complexes isolants)', 'Plâtrerie', 'Doublages collés type MAP (Mortier Adhésif pour Plaques) — complexe plaque + isolant collé directement au mur. Très répandu en rénovation rapide.', '[{"titre":"État du support","detail":"Support sain, sec (humidité < 5 %), sans poussière, sans peinture brillante. Décaper toute peinture glycéro ou laque qui empêcherait l''accrochage du MAP. Sur enduit ancien farineux : décaper et appliquer un primaire d''accrochage."},{"titre":"Plots de MAP","detail":"Diamètre 10 cm, épaisseur 2-3 cm, espacés de 30 à 40 cm. Plot toutes les 30 cm dans le sens vertical, 40 cm en horizontal. Quantité : environ 25 plots par plaque 1,20 × 2,50. Moins de plots = plaque souple qui sonne creux."},{"titre":"Implantation des plots","detail":"3 lignes verticales par plaque (gauche, milieu, droite) + plots en tête et en pied. Plots en tête à 10 cm du plafond, en pied à 10 cm du sol. Pour grandes hauteurs : ajouter une ligne horizontale médiane."},{"titre":"Désolidarisation des pieds","detail":"Cale plastique sous chaque plaque pour la maintenir à 1 cm du sol pendant 24 h. Le plinthe finale couvrira ce jeu. Sans désolidarisation : remontées d''humidité et risque de cloquage en pied."},{"titre":"Joints de fractionnement","detail":"Joint de dilatation tous les 6 m linéaires sur grandes longueurs. Sans joint, les variations thermiques font fissurer la plaque sur toute la longueur. Joint apparent à recouvrir d''un baguette PVC ou métal."},{"titre":"Pas de doublage collé sur support humide","detail":"Mur enterré, sous-sol, mur Nord humide : interdit, le MAP ne tient pas et la plaque pourrit. Préférer ossature métallique avec lame d''air ventilée, ou traiter l''humidité avant doublage."}]'::jsonb, '[{"titre":"Pose sur support humide","detail":"Le MAP perd toute adhérence, la plaque se décolle en quelques mois. Réparation : tout déposer, traiter l''humidité, repartir sur ossature métallique."},{"titre":"Plots de MAP insuffisants","detail":"Plaque qui sonne creux, ondulations visibles, fissures sur les joints. Vérifier la consigne : 25 plots/plaque, jamais moins."},{"titre":"Absence de désolidarisation pied","detail":"Fissures horizontales en pied de mur dans les 6 mois, remontées d''humidité, plinthe qui se décolle."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-25-42', false, 50),
  ('NF DTU 25.31', 'Plafonds suspendus', 'Plâtrerie', 'Plafonds suspendus en plaques de plâtre — suspentes, fourrures, charges admissibles.', '[{"titre":"Espacement des suspentes","detail":"Entraxe 1 m maxi dans le sens des fourrures, 1,20 m maxi perpendiculaire. Pour grandes portées : densifier (entraxe 80 cm) ou doubler les fourrures. Suspentes trop espacées = plafond qui flèche."},{"titre":"Choix des fourrures","detail":"F530 (épaisseur 0,5 mm) pour usage courant, F47 pour plafonds chargés ou de grande portée. Entraxe fourrures 50 cm pour BA13 (60 cm maxi). Au-delà, la plaque flèche entre les fourrures, visible en lumière rasante."},{"titre":"Charge admissible suspente courante","detail":"25 kg par suspente standard. Au-delà (chauffage clim, lustre lourd, spots multiples), prévoir suspente renforcée ou ancrage direct au plancher porteur. Toujours calculer le poids total réparti avant validation."},{"titre":"Suspente dédiée pour équipements lourds","detail":"Spots encastrés > 3 kg, ventilateur de plafond, lustre > 5 kg : suspente directe au support porteur (solivage, dalle béton). Ne jamais suspendre à la fourrure seule = arrachement garanti."},{"titre":"Joint périphérique de désolidarisation","detail":"Bande résiliente entre le rail périphérique et le mur, pour absorber les mouvements thermiques. Sans désolidarisation : fissures en jonction mur-plafond dans les 12 mois."},{"titre":"Sens de pose des plaques","detail":"Plaques perpendiculaires aux fourrures, jamais parallèles. Si parallèles, la plaque ne porte que sur 2 appuis = flèche garantie. La position des joints transversaux doit être décalée d''une ligne sur l''autre."}]'::jsonb, '[{"titre":"Spots encastrés sans suspente dédiée","detail":"Le poids du spot (et chaleur dégagée) déforme la fourrure puis fait tomber le spot. Très fréquent avec les downlights LED lourds des cuisines récentes."},{"titre":"Suspentes mal ancrées dans le solivage","detail":"Vis trop courtes (mini 50 mm dans le bois sain) ou plantées dans une vermoulure → arrachement progressif, le plafond flèche par paliers."},{"titre":"Plaques posées dans le sens des fourrures","detail":"Plaque ne porte que sur 2 appuis = flèche entre appuis dès la première année. Très visible en éclairage rasant."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-25-31', false, 60),
  ('NF DTU 45.10', 'Isolation des murs par l''intérieur (ITI)', 'Isolation', 'Très important pour la rénovation énergétique. Encadre l''ITI avec ses risques (point de rosée, ponts thermiques, humidité).', '[{"titre":"Diagnostic préalable obligatoire","detail":"Vérifier l''absence d''humidité dans le mur (humidimètre), l''état de la ventilation du logement (VMC ?), la nature et l''état du support. ITI sur mur humide = aggravation garantie. Sans VMC : reporter ou installer une avant."},{"titre":"Pare-vapeur côté chaud","detail":"Obligatoire pour R > 2 m².K/W (donc presque toujours en ITI). Le pare-vapeur empêche l''humidité du logement de migrer dans l''isolant et de condenser au contact du mur froid. Sd minimum 18 m. Toujours côté intérieur (côté chaud)."},{"titre":"Continuité du pare-vapeur","detail":"Adhésifs spécifiques à toutes les jonctions de lés (recouvrement 10 cm + adhésif). Étanchement aux passages de gaines, prises électriques, boîtiers. Un seul trou = pont de vapeur localisé = condensation et moisissures."},{"titre":"Traitement des ponts thermiques","detail":"Retour d''isolant en tableau de fenêtre (3-4 cm), sous-face du plancher haut (40 cm dans la pièce), refends à isoler sur 60 cm depuis le mur extérieur. Sans ces retours : tâches noires d''humidité aux jonctions, perte de l''efficacité énergétique."},{"titre":"Ventilation du logement obligatoire","detail":"VMC simple ou double flux active. Sans VMC, l''humidité produite par les occupants (3-5 L/jour pour une famille) ne s''évacue plus → condensation, moisissures, dégradation de l''isolant. C''est non-négociable."},{"titre":"Pas d''ITI sur mur extérieur humide","detail":"Mur ancien à remontées capillaires, mur enterré non drainé, mur de cave non traité : interdit. L''humidité reste piégée derrière l''isolant et détruit le mur. Traiter d''abord la source d''humidité, attendre 6 mois, puis isoler."},{"titre":"Qualification RGE pour les aides","detail":"Pour bénéficier de MaPrimeRénov'' et CEE, l''entreprise doit être RGE Qualibat ou Qualifelec mention spécifique. Sans RGE : pas d''aides pour le client, donc projet potentiellement annulé."}]'::jsonb, '[{"titre":"ITI sans pare-vapeur","detail":"L''humidité condense au contact du mur froid, l''isolant pourrit, des moisissures apparaissent côté intérieur dans les angles. Souvent invisible 2-3 ans puis explose en sinistre."},{"titre":"Pas de retour d''isolant en tableau","detail":"Pont thermique localisé au tableau de fenêtre → condensation, tâche noire, peinture qui cloque. Très fréquent sur les chantiers menés trop vite."},{"titre":"ITI sur mur humide","detail":"L''humidité monte de plus belle (plus moyen d''évaporer), le salpêtre apparaît, l''isolant et la plaque pourrissent. Sinistre majeur, dépose totale obligatoire."},{"titre":"Pas de VMC dans le logement","detail":"L''humidité de l''air ne s''évacue plus, condense sur les murs froids restants (ponts thermiques) et l''isolant. Moisissures dans les semaines suivantes."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-45-10', true, 70),
  ('NF DTU 45.11', 'Isolation des combles par panneaux et rouleaux', 'Isolation', 'Isolation des combles perdus et aménagés en laine minérale ou biosourcée.', '[{"titre":"Pare-vapeur côté chaud","detail":"Pour combles aménagés : pare-vapeur entre l''isolant et la plaque de plâtre, côté intérieur chauffé. Pour combles perdus : pas obligatoire en zone H1/H2 si plancher des combles bien étanche à l''air, mais recommandé."},{"titre":"Épaisseur pour combles perdus","detail":"30 à 40 cm pour atteindre R ≥ 7 m².K/W exigé par MaPrimeRénov''. Laine soufflée ou rouleaux croisés. Sans cette épaisseur : pas d''aides client + performance énergétique insuffisante."},{"titre":"Combles aménagés : 2 couches croisées","detail":"Première couche entre chevrons (20-22 cm), deuxième couche perpendiculaire en sous-face (10 cm minimum). Le croisement supprime les ponts thermiques le long des chevrons."},{"titre":"Distance de sécurité conduits de fumée","detail":"50 cm minimum entre laine et conduit de fumée non isolé. Au contact : risque incendie majeur. Utiliser des protections incombustibles (laine de roche haute densité, écrans). Vérifier aussi pour spots LED encastrés (étanches à l''air type Klüber)."},{"titre":"Boîtiers électriques étanches à l''air","detail":"Tout boîtier traversant le pare-vapeur (interrupteurs au plafond, spots) doit être en version étanche IP24 + manchette d''étanchéité. Sans ça : courant d''air et perte thermique massive."},{"titre":"Trappe d''accès isolée","detail":"La trappe doit avoir le même R que le reste du plancher, avec joint d''étanchéité à l''air. Une trappe non isolée = pont thermique géant + courant d''air permanent."}]'::jsonb, '[{"titre":"Pare-vapeur déchiré ou discontinu","detail":"Condensation localisée, l''isolant se gorge d''eau et perd ses performances. Tassement progressif des laines avec pertes thermiques jusqu''à -50 %."},{"titre":"Tassement de la laine en vrac","detail":"Avec le temps, la laine soufflée se tasse de 10 à 15 %. Mauvaise installation = tassement majeur la première année. Toujours souffler avec 10 % de surépaisseur."},{"titre":"Boîtiers électriques non étanches","detail":"Chaque boîtier non étanche = \"cheminée\" qui aspire l''air chaud du logement vers les combles. Multiplie les déperditions, surtout sur logement neuf RT2012."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-45-11', false, 80),
  ('NF DTU 60.1', 'Plomberie sanitaire', 'Plomberie', 'Le DTU central de la plomberie sanitaire — alimentation EF/ECS, multicouche, PER, cuivre. À connaître par cœur.', '[{"titre":"Pression de service","detail":"3 bars maxi en logement. Au-delà : réducteur de pression obligatoire en pied de colonne. Trop de pression = robinetterie qui s''use vite, chasses bruyantes, coups de bélier, fuites accélérées. Mesurer à l''entrée avant chiffrage."},{"titre":"PER (Polyéthylène Réticulé)","detail":"Jamais en apparent (UV le dégrade en 2-3 ans), toujours en gaine + dans les murs ou en faux-plafond. Distance feu : 30 cm minimum d''un conduit non isolé. Pose en couronne avec changements de direction par cintrage doux, jamais d''angle vif."},{"titre":"Cuivre — raccords","detail":"Raccords brasés (capillarité, soudo-brasage) ou bicônes pour raccordement amovible. Jamais de raccord fileté sur eau froide enterrée (corrosion). Brassage à l''argent obligatoire sur eau potable. Toujours tester à 1,5 fois la pression de service."},{"titre":"Multicouche","detail":"Raccords sertis avec témoin visuel obligatoire (couleur ou trait). Sertissage à la pince calibrée pour le diamètre. Contrôle au testeur de sertissage. Un sertissage raté = fuite différée dans 6-12 mois, derrière la cloison."},{"titre":"Pente d''évacuation","detail":"1 cm/m minimum sur tronçon horizontal, 2-3 cm/m optimal. Au-delà de 3 cm/m, l''eau s''écoule trop vite et n''entraîne pas les solides = bouchage. Vérifier au niveau laser sur les longs tronçons."},{"titre":"Robinet d''arrêt général","detail":"Accessible en pied de colonne ou dans le local technique, signalé par étiquette. Indispensable pour coupure d''urgence en cas de fuite. Robinet à boisseau sphérique 1/4 de tour, pas vanne à opercule (grippe avec le temps)."},{"titre":"Mise à la terre (équipotentialité)","detail":"Canalisations métalliques (cuivre, acier) reliées à la terre du tableau électrique. Liaison équipotentielle obligatoire en SDB (volume 0 à 3). Protège contre les chocs électriques par contact indirect."}]'::jsonb, '[{"titre":"PER apparent","detail":"Dégradation UV en 2-3 ans, fissuration, fuite. Très fréquent en local technique de cave non éclairé mais avec fenêtre. Toujours gainer ou maintenir hors lumière."},{"titre":"Raccord bicône sur eau chaude","detail":"Dilatation thermique répétée = joint qui se déforme, fuite goutte à goutte dans 6-12 mois. Préférer le bicône uniquement sur eau froide, et brasure pour eau chaude."},{"titre":"Pente d''évacuation insuffisante","detail":"Bouchage chronique de l''évier ou douche, odeurs remontantes (siphon désamorcé), nécessite débouchage à répétition. Vérifier avant fermeture de la cloison."},{"titre":"Test de pression non fait avant fermeture","detail":"Une micro-fuite sertissage non détectée explose en sinistre 3-6 mois après l''emménagement, derrière la plaque. Toujours mettre en pression 24 h à 1,5 × pression de service avant fermeture."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-60-1', true, 90),
  ('NF DTU 60.11', 'Règles de calcul plomberie', 'Plomberie', 'Dimensionnement des réseaux : diamètres, débits, pertes de charge. Essentiel pour les rénovations avec ajout de points d''eau.', '[{"titre":"Débits unitaires des appareils","detail":"Mitigeur lavabo : 0,2 L/s — Douche : 0,3 L/s — Baignoire : 0,33 L/s — Évier cuisine : 0,2 L/s — WC : 0,15 L/s — Lave-linge : 0,2 L/s. Mémoriser ces ordres de grandeur pour chiffrer rapidement un projet."},{"titre":"Coefficient de simultanéité","detail":"Tous les appareils ne servent pas en même temps. Coefficient de 0,3 à 0,5 selon nombre d''appareils. Le réseau dimensionné = somme des débits × coefficient. Sans ce coefficient, on surdimensionne et on perd de la pression."},{"titre":"Diamètres PER","detail":"Ø12 pour 1 point d''eau seul (PER), Ø16 pour 2-3 points groupés, Ø20 pour colonne principale ou nourrice. Sous-dimensionner = baisse de pression aux pointes d''utilisation. Surdimensionner = inertie thermique en ECS."},{"titre":"Diamètres d''évacuation","detail":"Lavabo Ø32 - Douche Ø40 - Baignoire Ø40 - Évier Ø40 - WC Ø100 (jamais moins). Bidet/urinoir Ø40. Toujours respecter pour éviter bouchage et siphon désamorcé."},{"titre":"Distribution en nourrice (PER)","detail":"Un départ Ø12 par appareil depuis une nourrice centralisée = pas de chute de pression quand un autre appareil ouvre. Beaucoup plus confortable que la distribution en série traditionnelle."}]'::jsonb, '[{"titre":"Sous-dimensionnement de la nourrice","detail":"Quand 2 robinets ouvrent en même temps, la pression chute. Particulièrement sensible en ECS (douche qui devient froide quand quelqu''un tire la chasse). Toujours partir d''une nourrice Ø20 ou Ø25."},{"titre":"Évacuation Ø32 sur douche italienne","detail":"Le débit d''évacuation est trop faible, l''eau stagne et déborde sur le sol. Imposer Ø40 minimum sur douche, et siphon de sol Ø50 sur douche XL."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-60-11', false, 100),
  ('NF DTU 60.31', 'Évacuation EU/EV (PVC)', 'Plomberie', 'Un des DTU les plus utilisés en expertise — beaucoup de pathologies d''odeurs et de bouchage viennent d''erreurs d''évacuation.', '[{"titre":"Pente d''écoulement","detail":"1 cm/m mini, 3 cm/m maxi. Au-delà : l''eau s''écoule trop vite sans entraîner les solides → bouchage par accumulation. En-dessous : stagnation et odeurs. Optimal : 2 cm/m."},{"titre":"Diamètres minimaux","detail":"Lavabo Ø32 — Douche/baignoire/évier Ø40 — WC Ø100 (jamais réduire). Buanderie : Ø50 minimum (machine à laver). Chaque réduction de diamètre = piège à bouchage."},{"titre":"Ventilation primaire en toiture","detail":"Conduit de chute prolongé en toiture, sortie au moins 50 cm au-dessus du faîtage et 1 m des baies. Sans cette ventilation, le passage d''eau crée une dépression qui désamorce les siphons = odeurs dans tout le logement."},{"titre":"Ventilation secondaire","detail":"Obligatoire si plus de 3 étages ou colonne en charge. Un conduit parallèle ramène l''air pour éviter les coups de bélier. Aérateur à membrane (Studor) accepté dans certains cas mais peu fiable à long terme."},{"titre":"Siphons et garde d''eau","detail":"Tous les appareils doivent avoir un siphon avec garde d''eau de 50 mm mini. Le siphon empêche les odeurs et germes de remonter. Pas de siphon = odeurs garanties, et risque sanitaire."},{"titre":"Raccordements sur descente","detail":"Jamais à 90°, toujours en culotte 45° + 45° pour amorçage progressif. Un coude brutal = bouchage récurrent et nuisances sonores."},{"titre":"Dilatation des canalisations","detail":"Le PVC se dilate avec la chaleur de l''eau (1 mm/m pour 25°C). Manchons de dilatation tous les 4 m sur conduit recevant de l''eau chaude. Sans cela : déformation, fuite aux raccords."}]'::jsonb, '[{"titre":"Pente excessive","detail":"Eau qui file sans entraîner papier et solides → bouchage répétitif, débouchage régulier nécessaire. Très fréquent quand on encastre une évacuation dans une chape épaisse."},{"titre":"Absence de ventilation","detail":"Siphons désamorcés à chaque tirage de chasse, odeurs d''égout permanentes dans la SDB. Très désagréable, parfois traité à tort par changement de WC."},{"titre":"Coude 90° brutal","detail":"Le débit ralentit brusquement, les solides s''accumulent à la jonction. Bouchage typique du WC qui se rebouche tous les 2-3 mois."},{"titre":"PVC blanc en extérieur","detail":"Le PVC blanc se fragilise sous UV en 5-8 ans, devient cassant, fuit aux raccords. Préférer le PVC gris (résistant UV) ou peindre le PVC blanc avec peinture acrylique."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-60-31', true, 110),
  ('NF DTU 64.1', 'Assainissement non collectif (ANC)', 'Plomberie', 'Fosses, filtres, épandages. Indispensable si tu interviens sur des maisons hors zone d''assainissement collectif.', '[{"titre":"Étude de sol obligatoire","detail":"Test de perméabilité (Porchet) avant tout dimensionnement, par bureau d''études agréé. Définit la filière compatible : épandage classique, filtre à sable, microstation. Sans étude : risque de système inadapté, refus SPANC, démontage."},{"titre":"Volume fosse toutes eaux","detail":"Volume minimum 3 000 L pour 5 pièces principales (PP). +1 000 L par PP supplémentaire. La fosse reçoit eaux vannes (WC) + eaux ménagères. Sous-dimensionnement = stockage insuffisant, débordement et nuisances."},{"titre":"Distances réglementaires","detail":"Fosse : 5 m mini de l''habitation, 3 m des limites séparatives, 35 m d''un puits. Lit d''épandage : 5 m de l''habitation, 3 m des limites, 35 m de tout point d''eau (puits, source, ruisseau). Ces distances protègent les ressources en eau."},{"titre":"Système agréé par le ministère","detail":"Seuls les systèmes inscrits sur la liste officielle du ministère de l''Écologie sont conformes. Vérifier la liste à jour avant achat. Système non agréé = refus SPANC, sanctions possibles."},{"titre":"Contrôle SPANC","detail":"Visite obligatoire à la conception (validation des plans) et à la réalisation (avant remblaiement). Sans visite finale : pas de certificat de conformité, vente du bien bloquée."},{"titre":"Pente du lit d''épandage","detail":"0,5 à 1 % maxi. Trop forte : eau ruisselle sans s''infiltrer. Trop faible : stagnation et colmatage. Calage au niveau laser indispensable."}]'::jsonb, '[{"titre":"Sous-dimensionnement / nombre de PP","detail":"Une chambre en plus dans le projet = 1 000 L de fosse en plus. Souvent oublié, conduit à un système saturé qui déborde dans le jardin."},{"titre":"Pas d''étude de sol","detail":"Épandage choisi sur sol argileux imperméable → eau qui remonte en surface, mauvais traitement, refus de conformité."},{"titre":"Pas de visite SPANC à la réalisation","detail":"Système enterré sans contrôle = aucun certificat. Le notaire bloque toute vente future. Coût de la reprise : 8 000 à 15 000 €."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-64-1', false, 120),
  ('NF DTU 68.3', 'Ventilation Mécanique Contrôlée (VMC)', 'Ventilation', 'LE DTU à connaître par cœur. Beaucoup de dossiers humidité / moisissures tournent autour de la VMC mal posée.', '[{"titre":"Caractère obligatoire","detail":"VMC obligatoire dans tout logement neuf depuis 1969 et rénovation lourde (changement de menuiseries + isolation). Sans VMC, les nouveaux logements étanches à l''air condensent partout. C''est non-négociable réglementairement et techniquement."},{"titre":"Pièces à extraction","detail":"Cuisine, salle de bain, WC, buanderie, cellier sans fenêtre. Le caisson aspire l''air humide et le rejette en toiture. Les pièces principales (chambres, séjour) n''ont pas d''extraction directe."},{"titre":"Entrées d''air dans les pièces principales","detail":"Grille au-dessus des fenêtres ou dans les caissons de volet, dans toutes les chambres et séjour. Indispensable : sans entrées d''air, la VMC met le logement en dépression → mauvaise extraction. Sections : 30 m³/h par pièce."},{"titre":"Position du caisson","detail":"Toujours en volume chauffé : combles aménagés isolés, faux-plafond chauffé, placard intérieur. Jamais en combles non isolés (gaines qui condensent + caisson qui gèle l''hiver). Erreur la plus fréquente sur les chantiers neufs."},{"titre":"Isolation des gaines en combles","detail":"Si les gaines passent en zone non chauffée : isolation manchon 25 mm minimum. Sans cela, l''air humide extrait condense dans la gaine et coule dans les bouches. Aussi : isolation acoustique pour absorber les bruits du caisson."},{"titre":"Débits réglementaires","detail":"WC : 15 m³/h — SDB : 30 m³/h (60 en double) — Cuisine : 75 m³/h (jusqu''à 135 m³/h hotte) — Buanderie : 30 m³/h. Vérifier au débitmètre lors de la mise en service. Débits insuffisants = humidité non évacuée."},{"titre":"Maintenance et nettoyage","detail":"Bouches d''extraction à démonter et nettoyer tous les 6 mois (graisse cuisine = colmatage rapide). Caisson : vérification annuelle + remplacement filtres si VMC double flux. À expliquer à l''occupant à la livraison."}]'::jsonb, '[{"titre":"Caisson en combles non isolés","detail":"En hiver, l''air humide extrait condense dans les gaines, l''eau redescend par les bouches en cuisine ou SDB. Tâches d''eau au plafond, signalées comme \"fuite de toiture\" à tort. Coûteux à reprendre."},{"titre":"Pas d''entrées d''air","detail":"La VMC met le logement en dépression sans pouvoir extraire correctement. Humidité stagnante, condensation aux fenêtres, moisissures dans les angles. Souvent l''occupant éteint la VMC qui \"ne sert à rien\" → catastrophe humidité."},{"titre":"Bouche cuisine non étanche","detail":"Graisse de cuisson qui colle, devient inefficace, bruit aspiré dans le caisson. Toujours installer une bouche cuisine adaptée (à clapet, débit variable)."},{"titre":"VMC arrêtée par l''occupant","detail":"Plainte récurrente : \"elle fait du bruit / consomme trop\". L''occupant débranche → humidité explose dans les semaines, moisissures dans les angles, dégradation des peintures. Expliquer à la livraison."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-68-3', true, 130),
  ('NF C 15-100', 'Installations électriques basse tension', 'Électricité', 'La bible de l''électricien. Toutes les règles de pose, sections, protections, volumes salle de bain, prises, tableaux.', '[{"titre":"Tableau électrique : réserve obligatoire","detail":"20 % de réserve mini (au moins 1 rangée libre). Permet l''ajout de circuits futurs sans changer le tableau. Tableau saturé = nouveau tableau à 1 500-2 500 € le jour où le client veut ajouter une borne de recharge ou une cuisine équipée."},{"titre":"Nombre minimum de circuits par logement","detail":"T1 (studio) : 4 circuits mini. T2 : 5. T3 : 6-7. T4 : 8-9. T5+ : 10+. Le compte inclut l''éclairage, prises, chaque circuit spécialisé (cuisson, LL, LV, SL, chauffe-eau, chauffage). Sous-dimensionner = client mécontent qui saute tout le temps."},{"titre":"Différentiel 30 mA — type AC ou A","detail":"Type AC (courant alternatif sinusoïdal) pour circuits courants. Type A obligatoire pour circuits avec composants électroniques : cuisson, lave-linge, sèche-linge, plaque induction, IRVE (borne véhicule). Type AC sur ces circuits = différentiel inopérant."},{"titre":"Nombre d''inter-différentiels 30 mA","detail":"Au moins 2 différentiels 30 mA obligatoire (2× type AC 40 A pour un T2). T4+ : 3 différentiels (2× AC + 1× A). Grosse cuisine + IRVE : 4 différentiels. Répartir les circuits pour qu''un défaut ne coupe pas tout le logement."},{"titre":"Sections de conducteurs","detail":"Éclairage : 1,5 mm² (8 points maxi par circuit, protection 16 A). Prises : 2,5 mm² (8 prises maxi, protection 20 A). Circuits spécialisés (lave-linge, cuisson) : 2,5 ou 6 mm² selon puissance, en disjoncteur dédié 20 ou 32 A."},{"titre":"Nombre minimum de prises par pièce","detail":"Séjour : 5 prises mini + 1 par 4 m² au-delà de 28 m². Chambre : 3 prises 16 A. Cuisine : 6 prises 16 A dont 4 au-dessus du plan de travail. Couloir/dégagement : 1 prise. Extérieur (balcon, terrasse couverte) : 1 prise étanche IPX4 mini."},{"titre":"Cuisine — circuits dédiés obligatoires","detail":"Plaque cuisson : circuit dédié 32 A en 6 mm² (2,5 mm² si plaque < 3000 W). Four : circuit 20 A en 2,5 mm² dédié. Lave-vaisselle : circuit 20 A dédié. Prises plan de travail : min 4 sur circuit 20 A dédié cuisine. Frigo/hotte : peuvent partager mais mieux séparés."},{"titre":"Salle de bain — volumes","detail":"Volume 0 (intérieur baignoire/bac) : aucun équipement. Volume 1 (au-dessus, 2,25 m) : chauffe-eau IPX5 acceptée. Volume 2 (60 cm autour) : éclairage IPX4, prise rasoir avec transfo. Volumes étendus à toute la pièce pour le chauffage électrique (IPX1). Prise 16 A hors volume, à 60 cm mini de la baignoire."},{"titre":"ETEL et GTL — obligatoires","detail":"ETEL (Espace Technique Électrique du Logement) : zone au sol dédiée au tableau, dimensions 60 × 25 cm mini, hauteur 2,25 m. GTL (Gaine Technique Logement) : goulotte verticale reliant l''ETEL au coffret de communication. Sans ETEL/GTL : non conforme, refus consuel."},{"titre":"Coffret de communication (VDI)","detail":"Obligatoire depuis 2016 pour tout logement neuf. Contient : DTI (arrivée téléphone/fibre), coffret de brassage RJ45, prise TV. Prises RJ45 dans séjour + chaque chambre. Minimum 2 prises RJ45 dans logement < 35 m², 6 prises en T4+."},{"titre":"AGCP et coupure d''urgence","detail":"AGCP (Appareil Général de Commande et de Protection) = disjoncteur d''abonné en tête de tableau, accessible entre 90 cm et 1,80 m du sol. Coupure d''urgence = celle-là même. Accessible sans clé ni outil. Refus consuel systématique si trop haut ou caché."},{"titre":"Mise à la terre","detail":"Obligatoire pour toutes les masses métalliques (radiateurs, baignoires métalliques, tableau). Section 6 mm² mini, raccordée à la barette de terre du tableau. Sans terre : sécurité personnes non assurée, refus consuel."},{"titre":"Liaison équipotentielle SDB","detail":"Obligatoire en SDB : reliage de toutes les masses métalliques (canalisations métalliques, bonde d''évier/baignoire métallique, radiateur) à la barette de terre. Section 2,5 mm² mini. Évite les différences de potentiel dangereuses au contact."},{"titre":"IRVE — borne véhicule électrique","detail":"Depuis 2020, tout logement neuf avec parking privatif : pré-équipement IRVE obligatoire (fourreau + place au tableau). Câble mini 4 mm² pour circuit 32 A dédié. Anticiper en rénovation lourde : compter 200-400 € pour ne pas avoir à retoucher le tableau plus tard."},{"titre":"DAAF — détecteur de fumée","detail":"1 DAAF obligatoire par logement depuis 2015, placé de préférence dans le couloir des chambres. Pas dans SDB/cuisine (fausses alarmes). Fourniture et pose incombent au propriétaire. Note : n''est pas dans NF C 15-100 mais loi Morange, à connaître."},{"titre":"Parafoudre","detail":"Obligatoire dans tableau si zone AQ2 (foudroyage > 25 jours/an), ou pour ERP. En zone normale : recommandé. Protège contre les surtensions atmosphériques qui peuvent griller toute l''électronique du logement (multimédia, électroménager)."}]'::jsonb, '[{"titre":"Section sous-dimensionnée","detail":"Circuit prise en 1,5 mm² au lieu de 2,5 mm² : échauffement à pleine charge, isolant qui durcit puis fond, risque incendie. Très grave et difficile à détecter sans contrôle."},{"titre":"Tableau saturé sans réserve","detail":"Le jour où le client veut ajouter une borne véhicule électrique, on doit changer tout le tableau (1 500-2 500 €). Toujours laisser au moins 6 modules vides à la livraison."},{"titre":"Prises en volume 1 SDB","detail":"Non conforme NF C 15-100, refus consuel obligatoire. Le consuel revient en visite (+ 200 €) après reprise. Toujours vérifier les volumes avant chiffrage."},{"titre":"Pas de différentiel 30 mA dédié","detail":"Différentiel unique pour tout le tableau = en cas de défaut, plus aucun circuit. Mauvais confort + dangereux. La norme exige 2 à 4 différentiels selon nombre de circuits."},{"titre":"Coffret de communication oublié ou trop petit","detail":"Beaucoup d''électriciens oublient encore le coffret VDI ou en posent un mini. Refus consuel garanti. Prévoir le grand format (à 6 RJ45 mini) même en petit logement pour anticiper."},{"titre":"GTL trop étroite ou fermée","detail":"GTL de moins de 20 cm de large ou traversée par des tuyaux d''eau : non conforme. Doit rester dédiée à l''électricité et à la communication, avec réserve d''espace pour évolutions."},{"titre":"Pas de circuit dédié cuisson","detail":"Plaque induction sur circuit prises = disjoncteur qui saute dès qu''on cuisine avec 2 plaques. Circuit 32 A dédié en 6 mm² obligatoire pour toute plaque > 3 000 W."},{"titre":"DAAF absent ou mal placé","detail":"Détecteur de fumée dans la SDB ou la cuisine : fausses alarmes en série (vapeur, buée, fumée cuisson). Doit être dans le couloir des chambres, sur le plafond, éloigné de 30 cm des murs."},{"titre":"Pas d''anticipation IRVE","detail":"Client qui achète une voiture électrique 2 ans après rénovation → nouveau tableau + circuit + fourreau, budget 800-1500 €. Toujours prévoir 1 disjoncteur libre 32 A + fourreau vers le parking."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/nf-c-15-100', true, 140),
  ('NF DTU 52.2', 'Carrelage collé', 'Carrelage', 'Les experts adorent ce DTU — beaucoup de sinistres carrelage viennent de non-respect des règles de support et de fractionnement.', '[{"titre":"État du support","detail":"Planéité contrôlée sous règle de 2 m : 5 mm maxi en sol, 3 mm maxi en mur. Humidité < 3 % CT (testée à la sonde) avant collage. Support fissuré : ponter avant carrelage. Sans contrôle = décollement et fissuration garantis."},{"titre":"Âge de la chape ciment","detail":"28 jours minimum avant pose, pour que le retrait soit terminé. Plus rapide = retrait pendant la prise de la colle = décollement. Tolérance 21 jours si humidité résiduelle vérifiée < 3 %."},{"titre":"Chape anhydrite","detail":"Ponçage + primaire d''accrochage obligatoires. L''anhydrite forme une croûte de surface qui empêche l''adhérence directe. Sans primaire : décollement en plaques en moins d''un an. Vérifier humidité < 0,5 % CM avant pose."},{"titre":"Sol chauffant","detail":"Mise en chauffe progressive avant pose : +5°C/jour jusqu''à 25°C, palier 7 jours, descente progressive. Pose carrelage seulement après cette mise en chauffe initiale. Pose puis arrêt 48 h pour la prise complète."},{"titre":"Choix de la colle","detail":"C2 minimum pour formats > 30 × 30, C2S pour grands formats > 60 × 60, C2 ET pour pose sur sol chauffant. Le S (déformabilité) absorbe les variations thermiques. Sans la bonne colle = carrelage qui sonne creux."},{"titre":"Double encollage","detail":"Obligatoire pour formats > 30 × 30 ou pose extérieure : colle au sol au peigne adapté + dos du carreau au peigne fin. Garantit le contact intégral. Sans double encollage : poches d''air sous le carreau, sonorité creuse, fissuration."},{"titre":"Joints de fractionnement","detail":"Tous les 40 m² maxi ou 8 m linéaires en intérieur, 25 m² en extérieur. Coupent les contraintes thermiques. Sans fractionnement = fissuration en diagonale typique sur grandes surfaces (séjour 50 m²)."},{"titre":"Joints périphériques","detail":"5 mm minimum contre tous les murs, masquables par les plinthes. Le carrelage doit pouvoir se dilater librement. Sans joint = soulèvement central (cloque) en quelques mois."}]'::jsonb, '[{"titre":"Pose sur chape anhydrite sans primaire","detail":"Décollement systématique en plaques 3-12 mois après pose. Réparation : dépose complète, ponçage, primaire, recollage. Très coûteux car le client a déjà emménagé."},{"titre":"Mauvais double encollage","detail":"Carreaux qui sonnent creux, déchaussement local au poinçonnement (talon, chaise), fissuration. Souvent invisible jusqu''à la 1ère casse."},{"titre":"Pas de joint de fractionnement","detail":"Fissuration en diagonale sur les grands espaces (séjour > 40 m²), typique des chantiers menés trop vite. Réparation = section fissurée à reprendre."},{"titre":"Pose sur sol chauffant non mis en chauffe","detail":"La chape se dilate pendant la première mise en chauffe sous le carrelage = décollement violent. Toujours faire le cycle complet de mise en chauffe avant collage."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-52-2', true, 150),
  ('NF DTU 51.1', 'Parquets cloués', 'Parquet', 'Parquet massif cloué sur lambourdes — pose traditionnelle des bâtiments anciens et belles rénovations.', '[{"titre":"Lambourdes","detail":"Bois sec (humidité < 14 %), traité classe 2, posé sur plots, hérisson ou solivage existant. Lambourdes habituellement 60 × 80 mm. Lambourdes humides = soulèvement du parquet par dilatation."},{"titre":"Entraxe des lambourdes","detail":"40 cm maxi pour lames 23 mm, 45 cm pour lames 27 mm. Au-delà : le parquet flèche entre lambourdes, grince à la marche. Toujours adapter à l''épaisseur de la lame achetée."},{"titre":"Clouage en biais sur la rainure","detail":"Clous spéciaux parquet (tête plate, fût lisse), enfoncés en biais à 45° dans la rainure pour qu''ils soient invisibles. Pas de clouage en face visible. Sans cette technique = têtes de clou apparentes."},{"titre":"Humidité du bois selon chauffage","detail":"9 % en chauffage central (parquet sec), 12 % en chauffage doux (poêle, cheminée). Acclimatation 48 h en place dans la pièce. Bois trop humide = retrait et jours après séchage. Trop sec = soulèvement par reprise d''humidité."},{"titre":"Joint de dilatation périphérique","detail":"8 mm minimum contre tous les murs, masqué par plinthe ou quart-de-rond. Le bois travaille toute l''année (saisons) : sans joint = cloquage central."},{"titre":"Acclimatation avant pose","detail":"Lames stockées 48 h dans la pièce de pose, paquets ouverts, pour équilibrage hygrométrique. Sans acclimatation : tuilage des lames ou jours apparents dans les semaines suivantes."}]'::jsonb, '[{"titre":"Pose sans acclimatation","detail":"Tuilage (les lames se déforment en V à cause de l''humidité) ou jours nets apparaissant après la première saison de chauffe. Très visible et difficile à corriger sans dépose."},{"titre":"Pas de joint périphérique","detail":"Le parquet pousse contre les murs en humidité haute, cloque au centre. Réparation = couper le parquet en périphérie sur 2 cm."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-51-1', false, 160),
  ('NF DTU 51.2', 'Parquets collés', 'Parquet', 'Parquet contrecollé ou massif collé en plein sur chape — solution courante en rénovation.', '[{"titre":"Planéité du support","detail":"3 mm sous règle de 2 m maxi. Au-delà : ragréage autolissant obligatoire. Sans planéité : décollement aux points hauts, sonorité creuse aux points bas. Le parquet collé exige un support irréprochable."},{"titre":"Humidité du support","detail":"< 2,5 % CM sur chape ciment, < 0,5 % CM sur chape anhydrite. Testée à la bombe au carbure (sonde). Coller sur chape humide = décollement systématique dans les semaines suivantes."},{"titre":"Choix de la colle","detail":"Colle MS Polymère ou polyuréthane mono-composant pour usage logement. Jamais de colle vinylique (à l''eau) sur sol chauffant ou parquet exotique. La fiche technique du parquet précise les colles autorisées."},{"titre":"Double encollage","detail":"Peigne adapté à la lame (n°4 ou 5 selon largeur). Colle au sol puis maroufler la lame fermement à la cale. Pas de plots, encollage en plein. Le parquet collé doit faire bloc avec le support."},{"titre":"Sol chauffant","detail":"Colle conductrice obligatoire (transmet la chaleur sans isoler). Résistance thermique totale parquet < 0,15 m².K/W (sinon le chauffage ne traverse pas). Vérifier la fiche technique de chaque parquet avant validation chauffage."},{"titre":"Joint périphérique","detail":"8 mm minimum contre tous les murs et points fixes (cheminée, colonne). Masqué par plinthe ou quart-de-rond. Sans ce joint, le parquet pousse les murs en dilatation."},{"titre":"Acclimatation","detail":"48 h dans la pièce, paquets ouverts. Indispensable surtout en hiver quand le chauffage assèche fortement l''air intérieur."}]'::jsonb, '[{"titre":"Mauvaise colle sur sol chauffant","detail":"Décollement par effet thermique, parquet qui sonne creux ou cloque. Très fréquent sur les rénovations rapides où on néglige la fiche technique."},{"titre":"Chape humide","detail":"Cloques et tuilage dans les semaines, parquet HS, dépose obligatoire. Toujours tester l''humidité avant collage."},{"titre":"Pas de joint périphérique","detail":"Soulèvement central, parquet en cloque. Réparation par recoupe périphérique = visible si parquet teinté."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-51-2', false, 170),
  ('NF DTU 51.11', 'Parquets flottants', 'Parquet', 'Parquet contrecollé en pose flottante — la solution rapide grand public (Quick-Step et autres).', '[{"titre":"Sous-couche obligatoire","detail":"Mousse 2-3 mm ou liège pour confort phonique et compensation des micro-défauts. Sous-couche acoustique (densité > 250 kg/m³) pour étage en copropriété. Sans sous-couche adaptée : bruit de pas transmis aux voisins du dessous."},{"titre":"Pare-vapeur","detail":"Sur dalle béton ou chape ciment : pare-vapeur PE 200 microns obligatoire, recouvrement 20 cm. L''humidité ascendante condense sous le parquet sinon → cloques. Pas nécessaire sur plancher bois ventilé."},{"titre":"Joint de dilatation périphérique","detail":"8 à 10 mm minimum, masqué par plinthes ou quart-de-rond. Idem aux passages de porte, cheminées, colonnes. Le contrecollé travaille toute l''année, jusqu''à 4-5 mm sur 5 m de longueur."},{"titre":"Surface maxi sans joint intermédiaire","detail":"8 m de large × 12 m de long. Au-delà : joint de dilatation transversal masqué par barre de seuil. Sans ce joint sur grand espace = soulèvement central typique."},{"titre":"Pose en quinconce","detail":"Décalage des têtes de lames d''au moins 30 cm d''une rangée à l''autre. Sans quinconce, structure trop régulière qui fragilise les emboîtements et donne un aspect \"trame\" visuel non souhaité."},{"titre":"Acclimatation","detail":"48 h en place, paquets ouverts à plat. Surtout en hiver où l''air ambiant peut être très sec (chauffage central) ou très humide (chantier humide)."}]'::jsonb, '[{"titre":"Pose sans pare-vapeur sur dalle béton","detail":"Cloques, tuilage, décollement des emboîtements. Le parquet \"joue\" et grince. Le client se plaint au bout de 6 mois."},{"titre":"Joint périphérique insuffisant","detail":"Le parquet pousse les plinthes vers l''extérieur, se cloque au centre. Sur grand séjour : très spectaculaire."},{"titre":"Sous-couche inadaptée","detail":"Grincements aux passages, transmission acoustique mauvaise. Sur étages : plaintes des voisins du dessous, recours en copropriété possible."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-51-11', false, 180),
  ('NF DTU 36.5', 'Mise en œuvre des fenêtres et portes extérieures', 'Menuiseries', 'Étanchéité à l''air et à l''eau des menuiseries — un point critique pour la performance thermique et l''absence d''infiltration.', '[{"titre":"Préparation du tableau","detail":"Contrôle aplomb, équerrage (diagonales égales à 2 mm près), planéité de l''appui. Reprise au mortier si désaffleur ou bosse > 5 mm. Sans cette préparation : menuiserie qui ferme mal, joint d''étanchéité distendu."},{"titre":"Fixation : pattes ou vis traversantes","detail":"Pattes scellées pour pose en applique avec rejingot, vis traversantes pour pose tunnel en réservation. Jamais en mousse polyuréthane seule (qui se rétracte de 5-10 % en quelques mois). Espacement vis : 70 cm maxi."},{"titre":"Étanchéité à l''air (intérieur)","detail":"Compriband précomprimé entre dormant et maçonnerie, côté intérieur. Joint mousse imprégné qui se dilate après pose et garantit l''étanchéité à l''air et à la vapeur. Évite condensation périphérique et fuites d''air."},{"titre":"Étanchéité à l''eau (extérieur)","detail":"Mousse PU expansive imputrescible + cordon de mastic neutre côté extérieur. La PU comble les vides, le mastic en plis cohérent évite l''infiltration. Toujours rester en compression, jamais en traction."},{"titre":"Bavette ou rejingot en pied","detail":"En pose applique : rejingot maçonné en pied de baie avec pente vers l''extérieur. En pose tunnel : bavette aluminium ou zinc avec ourlet. Sans cela : ruissellement direct dans la maçonnerie."},{"titre":"Calfeutrement périphérique","detail":"Joint silicone neutre (pas acide qui corrode l''alu) côté extérieur, en cordon plein continu de 5 mm. Le joint doit pouvoir bouger : sans calfeutrement compatible mouvement, fissure dans les premiers cycles thermiques."},{"titre":"Vitrage isolant performant","detail":"Standard rénovation : 4/16/4 argon (Ug 1,1 W/m².K). Performance maxi : 4/20/4 argon faiblement émissif (Ug 0,9). Pour MaPrimeRénov'' : vitrage avec Uw < 1,3 W/m².K obligatoire."}]'::jsonb, '[{"titre":"Mousse PU seule en étanchéité","detail":"La PU se rétracte de 5-10 % en quelques mois, créant un jour qui laisse passer l''eau et l''air. Très fréquent en pose rapide. Toujours doubler par joint mastic extérieur."},{"titre":"Pas de bavette en pied","detail":"L''eau ruisselle directement sur la maçonnerie, infiltrations en mur intérieur sous la fenêtre (peinture qui cloque). Sinistre courant en bâti ancien rénové trop vite."},{"titre":"Vissage en mousse seule","detail":"La menuiserie n''est tenue que par la mousse → arrachement progressif à chaque manœuvre. Au bout de 2-3 ans : la fenêtre bouge à la fermeture."},{"titre":"Pas de compriband","detail":"Fuites d''air permanentes, condensation périphérique côté intérieur, taches noires d''humidité aux angles. Très visible en hiver."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-36-5', true, 190),
  ('NF DTU 43.1', 'Étanchéité des toitures-terrasses', 'Étanchéité', 'À connaître même si tu sous-traites les couvreurs. Beaucoup de fuites de toiture-terrasse viennent de défauts de relevés et d''évacuations.', '[{"titre":"Forme de pente","detail":"1 % mini en toiture inaccessible, 1,5 % minimum en terrasse accessible. La pente garantit l''évacuation. Sans pente : flaques stagnantes qui dégradent l''étanchéité en quelques années (UV + cycles gel/dégel)."},{"titre":"Relevés d''étanchéité","detail":"15 cm minimum au-dessus du fil d''eau, fixés en tête par bande pincée ou profil métallique. Le relevé empêche l''eau de remonter sous l''étanchéité par battements de pluie. Sans bonne fixation en tête : décollement et infiltration."},{"titre":"Évacuations EP","detail":"2 évacuations minimum par toiture, dimensionnées avec surdimensionnement de 50 % (calcul EP + bouchage partiel possible). Une évacuation unique bouchée = mise en charge complète de la toiture, débordement intérieur."},{"titre":"Trop-plein obligatoire","detail":"Sortie de trop-plein en débord, calée au-dessus du niveau bas du relevé, en cas de bouchage des évacuations principales. Sans trop-plein : la toiture se remplit comme une piscine puis débord en façade ou en pignon."},{"titre":"Pare-vapeur sous isolant","detail":"Obligatoire en climat de plaine. Empêche la vapeur d''eau du logement de monter dans l''isolant, condenser et le pourrir. Position : sous l''isolant, côté chaud."},{"titre":"Lestage selon zone de vent","detail":"Toiture lestée par gravier (20 mm minimum), dalles sur plots ou végétalisation. Quantité selon zone de vent NV65 ou Eurocode 1. Sans lestage suffisant : décollement de l''étanchéité par effet de soulèvement."}]'::jsonb, '[{"titre":"Relevés insuffisants ou non fixés","detail":"Ruissellement derrière l''étanchéité, infiltration différée non détectable de l''extérieur. Tâches d''humidité au plafond du dernier étage, souvent attribuées à tort à une fuite de plomberie."},{"titre":"Évacuation unique bouchée","detail":"Mise en charge complète après une grosse pluie, débordement intérieur par les passages de gaines, sinistre majeur. Souvent dû à des feuilles ou de la mousse."},{"titre":"Pas de trop-plein","detail":"Si la principale est bouchée, aucune sécurité. La toiture se remplit jusqu''à débordement par le moindre point bas."}]'::jsonb, 'https://www.boutique.afnor.org/fr-fr/recherche/dtu-43-1', false, 200)
on conflict (lower(code)) do update set
  title         = excluded.title,
  domain        = coalesce(excluded.domain, public.dtu_sheets.domain),
  summary       = excluded.summary,
  key_points    = excluded.key_points,
  common_errors = excluded.common_errors,
  link          = coalesce(excluded.link, public.dtu_sheets.link),
  essential     = excluded.essential,
  position      = excluded.position,
  updated_at    = now();

-- ---------- Contrôle ----------
select count(*) filter (where key_points <> '[]'::jsonb) as fiches_documentees,
       count(*) filter (where essential)                 as mises_en_avant,
       count(*)                                          as fiches_au_total
from public.dtu_sheets;
